// th15_s7_b2 — Extra BossCard1 (spellEx 109) independent invulnerable shell.
// Source entry st07bs.ecl.txt:1323-1383; helper BossCard1_at st07bs.ecl.txt:1547-1584.
// Source frames are counted from the BossCard1 sub entry; its timerReset is source frame 4.
// The card shell gives a 120-frame opening buffer before the source timeline begins.

const TIME_LIMIT: int = 4324;
const OPENING_BUFFER: int = 120;

// TH15 type 27 (etSprite(0,27,0)) maps to the existing modern fireball-blue slot.
const TH15_FIREBALL_BLUE: int = 784;

// Source EX chain on every bullet:
//   etEx(2, ANIM a=1)                 -> birth anim omitted, its -4*speed offset kept
//   etEx(1048576, BRIGHT a=1)         -> pure visual
//   etEx(-2147483648, WAIT a=60)      -> explicit 60-frame delay before the angle effect
//   etEx(8, ANGLE_ACCEL a=100, r=-0.05, s=0.0034906585)
//     0.05 px/frame^2 along motion + 0.2 deg/frame angular velocity, 100 frames.
// The emitter's etDist(24) and the ANIM entry offset (-4 * 2.0 = -8 px) combine to a
// 16 px net spawn distance along each bullet angle.
xformdef BOSSCARD1_CURVE {
    wait(60);
    set_ang_vel(0.2deg);
    set_accel(-0.05fx);
    wait(100);
    stop_fx();
}

// Source BossCard1_at: one emitter configuration, then 100 x 3 fans of 6 bullets.
// %A starts at pi/2, decreases 1.5 deg per shot for F0=+1 (increases for F0=-1),
// and advances +45 deg per outer H step for F0=+1 (backwards for F0=-1).
sub boss_card1_at(dir: int) {
    var a: angle = 90deg;
    sh_reset(0);
    sh_sprite(0, TH15_FIREBALL_BLUE, 0);
    sh_aim(0, 0);                 // etAim(0,1): fixed-direction fan
    sh_ring(0, 0);                // fan geometry, not a full ring
    sh_count(0, 6, 1);            // etCount(0,6,1): 6 ways, 1 layer
    sh_speed(0, 2fx, 0fx);        // etSpeed(0,2,1): one layer at speed 2
    sh_angle(0, a, 45deg);        // etAngle(0,A,0.7853982): 45 deg way spacing
    sh_dist(0, 16fx);             // etDist(24) + ANIM retract (-4 * 2.0)
    sh_xform(0, BOSSCARD1_CURVE);
    for h in 0..100 {
        for i in 0..3 {
            sh_angle(0, a, 45deg);
            sh_fire(0);
            a = a + ((-dir * 273) as angle);   // 1.5 deg, source update after etOn
            wait(2);
        }
        a = a + ((dir * 8192) as angle);       // 2*pi/8 = 45 deg at the H boundary
    }
}

// Source BossCard1 body: clear/prepare, move, then repeat at(+1), at(-1).
// Runs on the boss itself as the phase pattern task, so it dies with the card.
sub boss_card1() {
    // Source frame 0: TIMEOUT==0 branch -> etCancel(640) around the boss.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(2);                       // source label +2 (frame 2)
    wait(2);                       // source label +2 (frame 4): timerReset point

    // Source frame 4: killAllAsync/enmKillAll, then movement reset and teleport.
    kill_all_enemies(KILL_SILENT);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_vel(0, 0deg, 0fx, EASE_LINEAR);       // moveVel(0,0)
    move_vel(0, 0deg, 0fx, EASE_LINEAR);       // moveVelTime(0,0,0,0)
    move_to(0, 0fx, 0fx, EASE_LINEAR);         // movePosTime(0,0,0,0)
    move_to(60, 0fx, 192fx, EASE_QUAD_OUT);    // movePosTime(60,4,0,192)

    // Source label +90 (absolute frame 94, i.e. 90 frames after timerReset),
    // then wait(60): first at() call is at 150 frames after timerReset.
    wait(90);
    wait(60);

    // $D = 10000; the timeout ends the run long before this counter runs out.
    var d: int = 10000;
    while d > 0 {
        boss_card1_at(1);          // %F0 = 1
        boss_card1_at(-1);         // %F0 = -1
        d = d - 1;
    }
    // Source BossCard1_1324/_1344:
    loop { wait(1000); }
}

async sub boss_pattern() {
    wait(OPENING_BUFFER);
    set_enemy_flag(ENEMY_NO_BODY, 0);   // body collision returns after the opening buffer
    boss_card1();
}

// The real boss owns the phase; the phase pattern task is its attack timeline and
// dies with the card, so firing stops at the source timeout.
async sub boss_main() {
    // Entry state from st07bs.ecl.txt:8-39: boss body/hurt boxes and entry position.
    set_invuln(65535);            // independent no-DPS shell
    set_hurtbox(20fx);            // setHurtbox(40,40): ordinary circular half-width
    set_hitbox(24fx);             // setHitbox(48,48): ordinary circular half-width
    set_enemy_flag(ENEMY_NO_BODY, 1);   // keep the opening buffer harmless
    phase_begin(0, boss_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    // Entry position from st07bs.ecl.txt:8-39 (movePos(0,128)); the card then
    // rebases to (0,0) and moves to (0,192) inside boss_card1.
    // HP path evidence: previous setInterrupt threshold 3000 (st07bs.ecl.txt:47);
    // the timeout path may enter with a different remainder, and the invulnerable
    // shell does not restore player DPS either way.
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
